def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def calculate_S(factors):
    S = 0.0
    for p, a in factors.items():
        S += a / p
    return S

solutions = []
for n in range(1, 4001):
    if n == 1:
        # S for n=1 is an empty sum, which is 0. 
        # g(1) = 1, 2*1 = 2. So n=1 is not a solution.
        continue

    factors = prime_factorization(n)
    S = calculate_S(factors)

    # We must check if S is *exactly* 1. Due to floating point arithmetic,
    # we check if S is very close to 1.
    if abs(S - 1.0) < 1e-9:
        solutions.append(n)

print("Solutions found:", solutions)

